import React from "react";
export const UrlContext = React.createContext();

export class UrlProvider extends React.Component {

  constructor(props) {
    super(props);
    this.state = {
      list: []
    }
  }

  loadUrlList = (res) => {
    console.log("UrlContext::loadUrlList");
    console.log(res);
    if (res?.data) {
      this.setState(() => ({
        list: res.data.data.listing
      }))
    } else {
      console.error("Some error occured", res);
    }
  }

  addUrl = (item) => {
    this.setState((prevState) => ({
      list: [...prevState.list, item]
    }))
  }

  render() {
    return (
      <UrlContext.Provider value={{
        ...this.state,
        initUrlList: (res) => this.loadUrlList(res),
        addItem: (item) => this.addUrl(item)
      }}>
        {this.props.children}
      </UrlContext.Provider>  
    )
  }

}

export const UrlConsumer = UrlContext.Consumer;
