import React, { useState } from "react";
import axios from "axios";
import { toast, ToastContainer } from 'react-toastify';
import { useNavigate } from "react-router-dom";
import UrlFormik from "./UrlForm";
// import UrlApi from "../data/UrlApi";
import { INSERT_URL_ROUTE } from '../config/routeConfig'
import "react-toastify/dist/ReactToastify.css";


const AddUrl = (props) => {

  // const navigate = useNavigate();
  const saveData = async (data) => {
    const reqObj = { originalUrl: data.url, urlName: data.urlName }
    // addUrl(reqObj, (res) => {
    //   // let { response: { data } } = res
    //   console.log("ADD_URL RESPONSE");
    //   console.log(res);
    //   if (res?.data) {
    //     console.log("AddUrl::res.data");
    //     console.log(res.data);
        
    //   }
    // })
    axios.post(INSERT_URL_ROUTE,
    { ...reqObj },
    {
      headers: {
        'Authorization': sessionStorage.getItem('token')
      }
    })
      .then(res => {
        console.log("Response::");
        console.log(res);
        // callback(res);
        let { data } = res;
        toast(data.message, {autoClose: 2000});
      })
      .catch(err => {
        console.log("Error::addUrl");
        console.log(err);
        let { response: { data } } = err;
        toast(data.message, {autoClose: 2000});
      })
  }
  
  return (
    <>
      <UrlFormik url="" urlName="" onSave={(data) => saveData(data)} />
      <ToastContainer />
    </>
  )
}

export default AddUrl;