import React from "react";
import { withFormik, Form, Field } from 'formik';
import { Link } from "react-router-dom";
import * as Yup from "yup";

const UrlForm = (props) => {
  const { errors, touched, isSubmitting } = props;
  // console.log("props");
  // console.log(props);

  return (
    <Form>
      <div>
        <label>
          URL
          <Field type="text" name="url" placeholder="Enter URL" />
        </label>
        <br/>
        <label>
          Name
          <Field type="text" name="urlName" placeholder="Enter Name" />
        </label>
        <br/>
        <button type="submit" disabled={isSubmitting} >Submit</button>
        <Link to="/url/list"><button>Back</button></Link>
        <br/>
        {touched.url && errors.url && <span style={{ color: "red" }}>{errors.url}</span>}
        {touched.urlName && errors.urlName && <span style={{ color: "red" }}>{errors.urlName}</span>}
      </div>
    </Form>
  )
}

const UrlFormik = withFormik({
  mapPropsToValues({url, urlName}) {
    return {
      url: url || '',
      urlName: urlName || ''
    }
  },
  validationSchema: Yup.object().shape({
    url: Yup.string().min(4, 'Invalid Url').required('Url required'),
    urlName: Yup.string().min(2, 'Name must be more than 2 chars').required()
  }),
  handleSubmit(values, formikBag) {
    const {setSubmitting, props, resetForm} = formikBag;
    console.log("handleSubmit::values");
    console.log(values);
    props.onSave(values);
    setSubmitting(false);
    resetForm();
  }
})(UrlForm);

export default UrlFormik;
