import React from "react";
import { BrowserRouter, NavLink, Route,  Routes } from "react-router-dom";
import { UrlProvider } from "./components/UrlContext";
import About from "./components/About";
import Login from "./components/Login";
import AddUrl from "./components/AddUrl";
import UrlPage from "./components/UrlPage";
import './styles/navbar.css';

const NavBar = () => {
  return (
    <nav className="navbar">
      {/* <div className="logo">Your Logo</div> */}
      <ul className="nav-links">
        <li><NavLink to="/url/list">List</NavLink></li>
        <li><NavLink to="/about">About</NavLink></li>
      </ul>
      <ul className="nav-links">
        <li><button disabled={true}>Logout</button></li>
      </ul>
    </nav>
  );
};

export default class App extends React.Component {
  render() {
    return (
      <UrlProvider>
        <BrowserRouter>
          <div>
            <NavBar />
            <Routes>
              <Route path="/" element={<Login />} />
              <Route path="/url/add" element={<AddUrl />} />
              <Route path="/url/list" element={<UrlPage />} />
              <Route path="/about" element={<About />} />
            </Routes>
          </div>
        </BrowserRouter>
      </UrlProvider>
    )
  }
}
