import React, { useState } from 'react';
import UrlApi from '../data/UrlApi';
import { useNavigate } from 'react-router-dom';
import '../styles/login.css';

const Login = () => {
  const navigate = useNavigate();
  const [emailId, setEmailId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);

  const handleLogin = async (e) => {
    e.preventDefault();

    // Here you would typically make a request to your authentication API endpoint
    // and handle the token response accordingly.
    // For simplicity, we'll simulate a successful login with a hardcoded token.
    
    try {
      // Simulating an API request
      // const response = await fetch('your-auth-api-endpoint', {
      //   method: 'POST',
      //   headers: {
      //     'Content-Type': 'application/json',
      //   },
      //   body: JSON.stringify({ username, password }),
      // });
      const data = { emailId, password };
      UrlApi.login(data, (err, res) => {
        console.log("UrlApi.login::res");
        console.log(err);
        console.log(res);
        if (err) {
          setError(err.data.message);
          return;
        }
        console.log('Login successful', res.data);
        sessionStorage.setItem('token', res.data.accessToken);
        navigate("/url/list");
      })

      // if (!response.ok) {
      //   // Handle non-successful response (e.g., invalid credentials)
      //   setError('Invalid credentials');
      //   return;
      // }

      // const data = await response.json();
      
      // // Assuming the API returns a token upon successful login
      // const { token } = data;

      // // Store the token in localStorage or a more secure storage option
      // localStorage.setItem('authToken', token);

      // // You may also want to redirect the user to another page upon successful login
      // // For simplicity, we'll just log a message here.
      // console.log('Login successful');
    } catch (error) {
      console.error('Error during login:', error);
      setError('An error occurred during login');
    }
  };

  return (
    <div className="container">
      <form className="form">
        <h2>Login</h2>
        <input
          type="text"
          id="emailId"
          name="emailId"
          placeholder="Email id"
          autoComplete="off"
          value={emailId}
          onChange={(e) => setEmailId(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password"
          id="password"
          name="password"
          autoComplete="off"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button onClick={handleLogin}>Login</button>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
};

export default Login;
