import React, { useContext } from "react";
import { UrlContext } from "./UrlContext";
import UrlData from "./UrlData";

const UrlList = () => {
  const urlConsumer = useContext(UrlContext);

  return (
    <>
      <table>
        <thead>
          <tr>
            <th>Label</th>
            <th>Short Url</th>
            <th>Count</th>
            <th>Date</th>
          </tr>
        </thead>
        <tbody>
          {
            urlConsumer.list?.length > 0 ? (
              urlConsumer.list.map(item => {
                return (
                  <UrlData key={item._id} urlData={item} />
                )
              })
            ) : (
              <tr>
                <td>N/A</td>
                <td>N/A</td>
                <td>N/A</td>
                <td>N/A</td>
              </tr>  
            )
          }
        </tbody>
      </table>
    </>
  )
}

export default UrlList;
