import React from "react";
import { UrlContext } from "./UrlContext";
import UrlApi from "../data/UrlApi";
import { Link } from "react-router-dom";
import UrlList from "./UrlList";

export default class UrlPage extends React.Component {
  static contextType = UrlContext;

  componentDidMount() {
    if (sessionStorage.getItem('token')) {
      UrlApi.listUrl({}, (res) => {
        console.log("UrlApi.listUrl::res.data");
        console.log(res.data);
        if (res?.data?.code === 200) {
          this.context.initUrlList(res);
        }
      })
    }
  }

  render() {
    return (
      <>
        <h1>URL Listing</h1>
        {
          sessionStorage.getItem('token') ? (
            <div>
              <UrlList />
              <br />
              <Link to="/url/add"><button>Add Url</button></Link>
            </div>
          ) : (
            <div>
              <h3>Not authenticated</h3>
              <Link to="/"><button>Back to login</button></Link>
            </div>  
          )
        }
      </>  
    )
  }
}
