import React from "react";
import { Link } from "react-router-dom";
import moment from "moment";
import { REDIRECT_URL_ROUTE } from "../config/routeConfig";

const UrlData = (props) => {
  const {shortUrl, urlName, timesClicked, createdAt} = props.urlData;
  const url = `${REDIRECT_URL_ROUTE}/${shortUrl}`;
  const date = moment(createdAt).format('MMMM Do YYYY, h:mm:ss a')

  return (
    <tr>
      <td>{urlName}</td>
      <td><Link to={url} target="_blank">{shortUrl}</Link></td>
      <td>{timesClicked}</td>
      <td>{date}</td>
    </tr>  
  )
}

export default UrlData;
